// Generated from Points de rencontre(3).pdf. Lore-only integration; the entire location corpus is MJ-only.
export const COMPENDIUM_POINTS_RENCONTRE_SOURCE = "Points de rencontre(3).pdf";
export const COMPENDIUM_POINTS_RENCONTRE_ARTICLES = [{"id":"verite-points-rencontre","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Points de rencontre — réseaux cachés","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Lieux","Réseaux"],"sections":[{"id":"definition","title":"Principe","level":2,"blocks":[{"type":"p","text":"Les points de rencontre sont des lieus aussi lambda d’apparence qu’ils ne sont importants pour les communautés qu’ils représentent. Généralement, ces lieux sont assez accessibles, les humains normaux n’ont juste aucun moyen de savoir la vérité caché derrière les clients réguliers."}]},{"id":"index","title":"Lieux documentés","level":2,"blocks":[{"type":"table","rows":[["Communauté","Lieu"],["Mages","Tour d’or"],["Mages","La Décharge"],["Mages / Loups-garous","M(agic) Casino"],["Mages","Grand Théâtre Milo"],["Angelus","Sugar Eden"],["Angelus","Dancing Rabbit"],["Angelus","Angels Never Cry"],["Angelus","Garage Ashford"],["Daemons","Purple Embers"],["Daemons","First Flame"],["Daemons","Cabinet Faith"],["Daemons","Night Feathers"],["Daemons / Rocréens & aliens","Raven Corporation HQ — Black Tower"],["Loups-garous","Tanières de Runyon Canyon"],["Loups-garous","Ivory Fangs"],["Loups-garous","Wild Angel Wolf"],["Orques & gobelins","Jadecenter « Palameta »"],["Orques & gobelins","Green Health — Fall Avenue"],["Orques & gobelins","Fuckalifornia"],["Orques & gobelins","Dream Vladic Tower"],["Orques & gobelins","Military Next Academy"],["Rocréens & aliens","QG Space Union Force / bureau californien de l’AIDH"],["Rocréens & aliens","Quartiers du clan Shaediri"],["Rocréens & aliens","Quartiers du clan Feeshri"]]}]}]},{"id":"points-rencontre-tour-or","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Tour d’or","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Mages"],"sections":[{"id":"dossier-mages-1","title":"Rôle pour Mages","level":2,"blocks":[{"type":"p","text":"Située dans le quartier des affaires, la « Tour dorée » est un bijou d’architecture, visuellement dorée, elle est un véritable phare la nuit. C’est le siège d’une association de grande ampleur, qui cherche à prôner l’éducation et l’amélioration des méthodes corporatiste, la tour dorée est, de fait, un institut académique indépendant. Tous les maitres de la Loge de Los Angeles y résident, bien en sécurité, leurs familles, leurs sorciers et tous ceux qui sont leurs partisans sont le personnel de la tour, si causer des dégâts à ce lieu causerait la fin de la loge de Los Angeles, c’est une théorie qui n’aura probablement jamais de pratique étant donnée à quel point le lieu est un nœud magique. La sensibilité des mages s’y trouvant est incommensurable, ils sentent sur une centaine de kilomètres les activités magiques, parfois de moindre ampleur. Même un dieu ne peut attaquer la tour avec toute sa puissance déchainée pour illustrer à quel point la Loge est en sécurité."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : MA Yimu ; Manika Rimmer."}]}],"illustration":{"src":"images/points-rencontre/tour-or.webp","alt":"Tour d’or","caption":"Tour d’or"}},{"id":"points-rencontre-decharge-san-diejuana","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"La Décharge","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Mages"],"sections":[{"id":"dossier-mages-3","title":"Rôle pour Mages","level":2,"blocks":[{"type":"p","text":"Située à l’extérieur de San Diejuana, la « Décharge » est au sens premier du terme une véritable décharge, une casse gigantesque où, sur des kilomètres, des détritus, véhicules et morceaux de bâtiment sont jetés. Malgré ses apparences, la Décharge n’est pas vide, de nombreux bâtiments, des préfabriqués sont installés et forme un réseau de « bunkers » magiques, partout dans les détritus, les mages de San Diejuana jettent des pièces ou des morceaux de métaux enchantés, y élèvent aussi des chiens et des chats magiquement modifiés, créant des millions de petites sources magiques servant à dissiper la magie ou les pouvoirs ennemis. En outre, dans se foutoir où on ne distingue rien, il est impossible de sentir si on est observé ou même maudit par une de ces pièces. Les Neopunks et autres crawlers composant les familles de Mages à Diejuana se rassemblent souvent dans des préfabriqués, c’est un pigeon artificiellement magique qui détermine lequel, au gré de ses envies de créature magique pensant et agissant comme un vrai pigeon. A la décharge, on l’appelle ce pigeon Paul. Alors que la tour dorée s’affiche clairement comme un bâtiment défiant toute attaque frontale, la Décharge est tout son contraire, elle est faite pour permettre de fuir par tous les côtés à ses mages, sous les détritus, un vaste réseau souterrain s’ajoute aux préfabriqués. Ce lieu étant isolé et détesté par les citoyens normaux, l’Hologramme est faible et permet aux jeunes mages de s’entrainer très aisément sous la tutelle de Mithridate, le président de la Loge."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Kristina Moon – « Frogchrist » ; Murck Date."}]}],"illustration":{"src":"images/points-rencontre/decharge-san-diejuana.webp","alt":"La Décharge","caption":"La Décharge"}},{"id":"points-rencontre-magic-casino","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"M(agic) Casino","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Mages","Loups-garous"],"sections":[{"id":"dossier-mages-5","title":"Rôle pour Mages","level":2,"blocks":[{"type":"p","text":"La grande réserve possède autant de casino que Las Vegas, ils sont aux frontières du territoires, ce sont des bâtiments énormes, positionnés dans des déserts rocheux, des forêts, sur des collines, presque toujours entourés d’un lac peu profond artificiel. Portes d’entrées de la grande réserve, ils sont aussi des forteresses pour sa défense, y concentrant l’essentiel du système de sécurité de la Tala corporation. Un de ces casinos, le « M » , nommé ainsi tout simplement puisqu’il en a la forme, est un des plus colossaux et des plus visités. Dirigé par Roowinu, un amerindien micmac, il reçoit des milliers de touristes depuis qu’il a été construit, en quelques semaines tant la Tala corporation est efficace dans la construction. Avec sa sécurité, son caractère isolé, le M est un prodigieux point de rendez-vous pour la pègre amérindienne que Muna dirige, négociant avec les gundrivers (les motards) et les émissaires d’autres mafias (italienne, russe et cartels essentiellement), aucune activité criminelle ne se fait sans avoir été acceptée et négociée ici. Le « M » n’est pas seulement un casino, c’est aussi le centre névralgique que la diplomatie surnaturelle amérindienne. En effet, la Loge de la Grande Réserve y a son QG. Les mages s’y rassemblent régulièrement mais pas seulement, puisque Talatuwa, la Grande meneuse des Pelages sombres, les loups-garous, consulte la Loge, notamment Muna, ses activités insurrectionnelles étant illégales, Réalité et Vérité s’entremêlent totalement dans leur cas. Le point de rendez-vous sert à trois choses : contourner la sécurité de la Tala pour les activités qu’elle ne tolère pas, défendre la Grande réserve en créant une synergie entre la Loge magique et les Pelages sombre, contre les Pelages roux, notamment, et d’autres loges magiques. Le « M » sert enfin de centre d’information, la sécurité du M, donc de la Tala, localement étant au service des Mages, tout ce qui se sait au sein de la Tala corp. Se sait à la Loge."}]},{"id":"dossier-loups-garous-33","title":"Rôle pour Loups-garous","level":2,"blocks":[{"type":"p","text":"La grande réserve possède autant de casino que Las Vegas, ils sont aux frontières du territoires, ce sont des bâtiments énormes, positionnés dans des déserts rocheux, des forêts, sur des collines, presque toujours entourés d’un lac peu profond artificiel. Portes d’entrées de la grande réserve, ils sont aussi des forteresses pour sa défense, y concentrant l’essentiel du système de sécurité de la Tala corporation. Un de ces casinos, le « M » , nommé ainsi tout simplement puisqu’il en a la forme, est un des plus colossaux et des plus visités. Dirigé par Roowinu, un amérindien micmac, il reçoit des milliers de touristes depuis qu’il a été construit, en quelques semaines tant la Tala corporation est efficace dans la construction. Avec sa sécurité, son caractère isolé, le M est un prodigieux point de rendez-vous pour la pègre amérindienne que Muna dirige, négociant avec les gundrivers (les motards) et les émissaires d’autres mafias (italienne, russe et cartels essentiellement), aucune activité criminelle ne se fait sans avoir été acceptée et négociée ici. Le « M » n’est pas seulement un casino, c’est aussi le centre névralgique que la diplomatie surnaturelle amérindienne. En effet, la Loge de la Grande Réserve y a son QG. Les mages s’y rassemblent régulièrement mais pas seulement, puisque Talatuwa, la Grande meneuse des Pelages sombres, les loups-garous, consulte la Loge, notamment Muna, ses activités insurrectionnelles étant illégales, Réalité et Vérité s’entremêlent totalement dans leur cas. Le point de rendez-vous sert à trois choses : contourner la sécurité de la Tala pour les activités qu’elle ne tolère pas, défendre la Grande réserve en créant une synergie entre la Loge magique et les Pelages sombre, contre les Pelages roux, notamment, et d’autres loges magiques. Le « M » sert enfin de centre d’information, la sécurité du M, donc de la Tala, localement étant au service des Mages, tout ce qui se sait au sein de la Tala corp. Se sait chez les Pelages sombres."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Mukna ; Lana Alvarez ; Sikya HAWKINS ; Ron Smith."}]}],"illustration":{"src":"images/points-rencontre/magic-casino.webp","alt":"M(agic) Casino","caption":"M(agic) Casino"}},{"id":"points-rencontre-grand-theatre-milo","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Grand Théâtre Milo","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Mages"],"sections":[{"id":"dossier-mages-7","title":"Rôle pour Mages","level":2,"blocks":[{"type":"p","text":"La Situé dans les plus beaux quartiers de Los Angeles, le grand théâtre Milo est connu pour appartenir à la Famille Luciano, la grande famille ayant la main sur la mafia Italo-américaine de Los Angeles en 2035. Il ne donne pas beaucoup de grands spectacles, mais fait salle comble quand cela arrive. Le reste du temps, la salle est donc louée. Elle est louée par un certain Ryan Foster (Faust) bien qu’il ne s’y présente jamais lui-même et une fois par semaine sert donc aux plus prestigieuses enchères d’antiquités et objets de curiosité de toute la Californie. Plus concrètement, ce sont les enchères magiques les plus prestigieuses du monde. On n’y vend pas que des objets, mais aussi des sorts, des formations, des renseignements. C’est la face la plus glorieuse de ces enchères, tous les mages du monde y venant, mettant de côté leurs relations tumultueuses dans l’unique but d’améliorer connaissances et collections. La face la plus sombre est d’autant plus malsaine, puisque ce qui se vend le plus cher n’est autre que le Mageius. Un Mageius est volatile et s’attache à un corps une fois que l’âme n’est plus dans celui où le Mageius se trouvait, donc sont vendu des gens bien vivants, dotés de Mageius, dans l’unique but de les sacrifier pour conférer plus tard à quelqu’un d’autres le mageius acheté. Ce n’est même pas de l’esclavage, c’est de la consommation de vie humaine. D’ailleurs, ne sont pas vendu qu des humains, mais Dives, Amazones ou Babayaga le sont aussi quand on en capture, tous les voyageurs dotés d’un Mageius peuvent finir ici. Le commerce humain ne s’arrête pas là, on vend aussi des ovules ou du sperme de grands mages afin d’améliorer la grandeur magique de la descendance. S’y vendent aussi des sorciers et des descendants, certaines familles échangeant leurs enfants, même dotés d’un Mageius afin d’acheter des amitiés à des familles plus puissantes ayant moins d’héritiers."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Tina Miller ; Rupert Sven Andersen."}]}],"illustration":{"src":"images/points-rencontre/grand-theatre-milo.webp","alt":"Grand Théâtre Milo","caption":"Grand Théâtre Milo"}},{"id":"points-rencontre-sugar-eden","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Sugar Eden","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Angelus"],"sections":[{"id":"dossier-angelus-9","title":"Rôle pour Angelus","level":2,"blocks":[{"type":"p","text":"Si les daemons ont le « first Flame » pour aller boire un coup et se trouver un ou une prostituée de grandes compétences, les anges ont le « Sugar Eden ». Tenu par Jcube, un séraphin de Zophielle, c’est aussi un bar d’hôtes, de grand standing, probablement nettement au-dessus du First Flame en termes de produits, meilleurs alcools, marbre véritable, de l’or sur les tables, ce que le Sugar Eden n’a pas en discrétion et confort, il le compense en luxe pur, ostensible et inutile. Malgré la rivalité assumée, les deux bars n’ont pas totalement la même clientèle sans même parler des clients inhumains. Concernant les anges, justement, ils viennent avant tout boire « la grâce de Dieu » un alcool qui sent et a le gout de n’importe quel vin d’orange pour quiconque le boit, mais qui, pour eux, a la capacité de les mettre en trance, éveillant leurs pouvoirs, agitant leur marque. Un angelus ne connait rien de tel, la sensation de recevoir cette bénédiction pure est plus orgasmique que n’importe quelle jouissance physique. Certains en abusant perdent d’ailleurs le gout à toute forme d’amusement. La « grâce de Dieu » est une vraie drogue, même si ça ne dure qu’une minute à peine, elle confère la puissance d’un Archange à n’importe quel simple angelus. Outre cette extase, ils viennent chercher des renseignements et des contacts, le >Sugar Eden ayant un catalogue de contacts non angéliques pour aider les jeunes plumes à réussir leur mission. On n’y croise toutefois pas souvent Elynea en personne, puisqu’elle n’apprécie pas spécialement ce bar, trop luxueux et prétentieux pour ce qu’il est."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Margareeta Rootare ; Jamal Jace Jayson (J3."}]}],"illustration":{"src":"images/points-rencontre/sugar-eden.webp","alt":"Sugar Eden","caption":"Sugar Eden"}},{"id":"points-rencontre-dancing-rabbit","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Dancing Rabbit","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Angelus"],"sections":[{"id":"dossier-angelus-11","title":"Rôle pour Angelus","level":2,"blocks":[{"type":"p","text":"Située dans un quartier gouvernemental en partie, en partie abandonné, le Dancing rabbit est possiblement le plus grand Nightclub, en superficie et en renommée, de tout Los Angeles. Par un tunnel il est relié à l’angel’s Table, un restaurant de très haut standing et de renommée mondiale, mais seul le personnel habilité connait le lien entre les deux. Possédé par Drasko Vladic, c’est son QG, puisque sous le club, les bureaux de son association se trouvent. C’est plus réalistement le QG officiel de la Bratva, la mafia russe. Le club possède une partie bar que tient Galya, la gérante officielle, souriant et avenante, ce n’est qu’une humaine normale quoi qu’elle soit bien moins le pantin qu’on imaginerait, œuvrant dur et continuellement pour faire du club ce qu’il est. Si ce lieu est si cher aux yeux des anges, c’est parce que d’une part, L’archange Urielle l’a choisie comme lieu de travail, faisant danseuse et serveuse dedans, toutes les nuits. Elle y adore l’ambiance et ne se ménage pas une seconde, adorant Galya et son épouse, Svetlana, laquelle passe souvent. La présence de Svetlana attire aussi la seconde raison : Elynea, bien qu’elle ne passe qu’occasionnellement, c’est un des rares lieu où les Archanges peuvent venir la voir, hélas pour eux, c’est aussi un des pires moments souvent. Sa présence renforce à elle seule les angelus, même sans l’aborder, il est donc avantageux de chercher à l’approcher. Comme ils sont attirés, les anges en profitent pour négocier, échanger et discuter, libres de l’influence de leur archange, grâce à la présence d’Elynea mais aussi, inconsciemment, de Svetlana. Les lieux ont une très forte affluence angélique donc, mais ne sont pas du tout dédiés à se manifester de manière surnaturelle, la rigueur et la discrétion sont donc plus qu’imposées."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Arielle Nova ; Rosina Vyacheslavovna."}]}],"illustration":{"src":"images/points-rencontre/dancing-rabbit.webp","alt":"Dancing Rabbit","caption":"Dancing Rabbit"}},{"id":"points-rencontre-angels-never-cry","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Angels Never Cry","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Angelus"],"sections":[{"id":"dossier-angelus-13","title":"Rôle pour Angelus","level":2,"blocks":[{"type":"p","text":"Les nightclubs de crawlers, de neopunks ne sont pas souvent fixes, ils sont souvent déménagés par leurs propriétaires ou réduits en poussières par les attaques corporatives. L’un des plus grands nightclubs illégaux est l’ANC, tenu par le plus célèbre encore JJN, le DJ neopunk le plus connu de tous, un des meilleurs amis de Damon Harrington « red Hadès ». Contrairement à bien des lieux de concert ou de fêtes, l’ANC est défendu, et aucune attaque ne l’a jamais détruit ou menacé. En soit, ce n’est pas un point de rencontre très pratique, la grande salle au son hurlant, les foules toujours plus violentes, il y a forcément mieux, mais le réseau souterrain de l’ANC permet d’avoir des centaines de petites salles de stockage de matériel et de réunions, permettant aux neopunks et aux insurgés de s’organiser, de négocier avec la pègre dans la majorité des cas, entre le reste du temps. Jesus Kenobi est un Séraphin de Sandalphon qui est devenu un loyal d’Urielle, derrière ses longs cheveux roux, il assure la sécurité des anges venus négocier aux sous-sols, en effet, son pouvoir semble être assez terrifiant puisque dans sa grande salle, ceux qui s’y trouvent sont sous son contrôle en partie. On n’y retrouvera pas souvent des Archanges néanmoins, même les séraphins y sont rares, le lieu est assez mal famé, alors seuls les crawlers les plus aguerris, les plus robustes et les plus badass ont vraiment leur place pour accéder à une salle secrète. Les autres se font vite broyés par la sécurité des neopunks, une Leslie Wright n’allant pas laisser n’importe qui trainer près de ses guitares par exemple. Urielle peut y passer, mais généralement, elle envoie des mafieux russes qu’elle a manipulé ou bien de pauvres anges pas vraiment prêts, pour les endurcir."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : « Jesus Jack Kenobi » - Jack Ken ; Barbara Amble."}]}],"illustration":{"src":"images/points-rencontre/angels-never-cry.webp","alt":"Angels Never Cry","caption":"Angels Never Cry"}},{"id":"points-rencontre-garage-ashford","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Garage Ashford","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Angelus"],"sections":[{"id":"dossier-angelus-15","title":"Rôle pour Angelus","level":2,"blocks":[{"type":"p","text":"Situé en plein cœur de Los Angeles, le Garage Ashford est une institution. C’est avant tout, le seul garage qui fait ses propres pièces automobiles d’avant les années 2010 , aucun modèle n’étant plus produit, aucune corporation ne s’amusant à produire des pièces, tout véhicule plus ancien n’a pratiquement plus aucune chance d’être entretenu. Les collectionneurs ayant des modèles plus anciens sont absolument contraints à passer par le Garage pour changer les pièces, mais il n’y a pas de quoi se plaindre, bien que cher, elles sont faites presque artisanalement et sont bien plus durables. Il en va de même avec les vieilles armes, les amateurs de révolvers ou de fusils à l’ancienne n’ont pas vraiment de quoi se faire plaisir, le garage produit ses propres pièces et fabrique lui￾même ses armes sur mesures au besoin. Le garage est un morceau du « saint Arsenal », de l’ordre d’Arianwen, Jack Ashford travaille pour Sœur Sacha (Sacha Novogvna), il possède donc des véhicules et des armes de chasseurs de l’Eglise, bien cachés dans sa réserve, il fournit les troupes de chasseurs, d’exorcistes et d’inquisiteurs, sans aucun frais et fourni de brèves formations à des équipements inhabituels. Le garage est tenu par d’ancien bikers, tous religieux, des moines musculeux et tatoués qu’il ne vaut mieux pas défier, tous ayant une clé à molette et un flingue à leur ceinture. Jack Ashford est toutefois un ange, malgré ses airs de Père Noël biker, il sert l’ancien archange Sachielle. C’est une Vertu, il assure donc en partie d’équiper les angelus servant encore Sachielle et ceux servant Zophielle, presque toujours des angelus implanté dans les religieux. Il aime assez peu les autres archanges, alors son crucifix l’aide à cacher sa nature angélique, ceux, pas assez attentifs, le prennent alors pour un simple humain. Malgré ce mépris, il aidera quand même les anges se révélant à lui, selon si cela va avec les plans ou non de Sachielle."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Jack Ashford ; Elisenda Ruiz."}]}],"illustration":{"src":"images/points-rencontre/garage-ashford.webp","alt":"Garage Ashford","caption":"Garage Ashford"}},{"id":"points-rencontre-purple-embers","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Purple Embers","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Daemons"],"sections":[{"id":"dossier-daemons-17","title":"Rôle pour Daemons","level":2,"blocks":[{"type":"p","text":"Si on prend le Temple de Lilith, quatre lieux de débauche notable lui étant associés, et que l’on trace un pentacle, le centre de ce dernier désigne l’exacte position du « Purple Embers ». Nightclub la nuit, café le matin et bar à toute heure, ce lieu de rencontre et de festivités n’est pas le Temple de lilith mais c’est portant lui qu’elle a choisi comme centre névralgique de son réseau d’influence. Tenu par Aessa, une duchesse démoniaque, le « Purple Embers » a été créé pour servir de sanctuaire généraliste à tous les daemons de la Terre après la crise de 2018, où Sharith s’éveilla et quelques créatures devinrent folles. En 2031, Belphegor, un autre duc de Lilith, fut tué par l’archange Camaelle, laissant Aessa seule pour gérer le bar, ne pouvant plus enquêter elle￾même. Le lieu semble être fait pour la débauche bisexuelle, des estrades avec des barres de pole dance sont situées régulièrement et très souvent utilisées, les tables sont larges pour accueillir d nombreuses personnes et pouvoir s’y allonger, les alcools sont presque tous sucrés pour qu’on en consomme sans interruption. L’ambiance est chatoyante et la musique diffusée est immensément enchantée par des voix daemoniaques de succubes. Agréable et sensuel, en soit, le club permet de presque toujours trouver chaussure à son pied, et contrairement à « First Flame », un autre bar démoniaque, il n’est vraiment pas besoin de payer les partenaires qu’on trouve au Purple, tout est fait avec plaisir et bénévolement. A côté, les démons viennent échanger des informations, Channel 666 passe en boucle sur des petits écrans, c’est une chaine de Nextar tenue par des daemons d’Astharoth. On échange des sortilèges, des adresses, des infos et des noms entre deux verres ou deux danses. La mieux informée est sans aucun doute Aessa elle-même quel que soit le sujet désiré et le prix est souvent celui d’une information ou d’un service en retour, rien de grave."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Amber Nichols ; Aessa Lee Love."}]}],"illustration":{"src":"images/points-rencontre/purple-embers.webp","alt":"Purple Embers","caption":"Purple Embers"}},{"id":"points-rencontre-first-flame","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"First Flame","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Daemons"],"sections":[{"id":"dossier-daemons-19","title":"Rôle pour Daemons","level":2,"blocks":[{"type":"p","text":"Située Dans un quartier abandonné racheté par des associations, le « First Flame » compte comme un des sept bars et night-club de sa rue. Ambiance assez chic et tamisée, c’est un bar d’hôtes. Les clients peuvent boire avec des hommes ou des femmes (des « hookers »), qui sont des spécialistes de la compagnie, ces hôtes et hôtesses, font parler, boire, ils font rire, ils sont amicaux, rassurants, et comme en 2035 la prostitution est légale en Californie, on peut aisément les toucher ou coucher avec, tout cela est tarifé. « First Flame » offre des services de qualité et un contexte rassurant, on peut aisément venir et profiter, les nombreuses salles et les rideaux permettant de limiter les yeux trop curieux. Bar de référence pour les Daemons de Belial, il est assez mal vu de venir en grand nombre pour des affaires daemoniaques. On trouve ironiquement souvent des angelus de la rue d’en face, qui viennent changer d’idée ici. Tous les hôtes et hôtesses sont des démons de Belial dans ce bar, cependant, ils assistent volontiers les autres serviteurs des dieux. Le bar n’est pas un temple, ce n’est pas non plus un lieu neutre, il arrive donc qu’il soit attaqué, Comme Moloch n’est pas un daemon normal, il est rare que la déesse Belial ne cherche à le venger quand cela arrive. En revanche, ceux qui doivent un service à Moloch sont nombreux, et eux le vengent assez volontiers. Bien que tenu par des démons de Belial, cette dernière étant la Reine des dieux, le bar reste un lieu apprécié des daemons en général, quand ils ont besoin d’un lieu calme et discret pour des négociations, ils le préfèrent au Purple Embers."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Jimmy Brazier ; Meryl West."}]}],"illustration":{"src":"images/points-rencontre/first-flame.webp","alt":"First Flame","caption":"First Flame"}},{"id":"points-rencontre-cabinet-faith","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Cabinet Faith","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Daemons"],"sections":[{"id":"dossier-daemons-21","title":"Rôle pour Daemons","level":2,"blocks":[{"type":"p","text":"La corporation de la « First Lawyers Incorporated » (FiLaw ou FLInc) possède le cabinet « Faith ». Il ne s’agit pas d’un cabinet d’avocat aux proportions industrielles, même s’il possède une renommée immense. Le cabinet Faith est situé dans le quartier des « lois », sensiblement le quartier de la corporation en vérité. C’est dans ce bâtiment que l’on trouve la co-fondatrice du cabinet et la vice￾présidente officielle de la corporation : Belyandra Queen. Le personnel du cabinet n’a rien de démoniaque, il est composé d’humains ou de non-humain sans aucune distinction. Belial est toutefois assistée de Demona Prince, une de ses duchesses les plus loyales. Si souvent on pense que Demona est uen secrétaire tant elle est au service de Belyandra, elle est une avocate à part entière qui gère des dossiers d’importance. Le bureau de Belyandra est sa salle du trône. Comme il s’agit de son temple, aux étages supérieurs, sont installés les prophètes de Belial, le Prophète du feu, celui de la domination, celui de la destruction, ou bien encore celui de la Puissance, ils possèdent tous leur bureau à cet étage, « l’étage des prophètes ». Evidemment, ils ne sont pas là ad vitam, siéger est symbolique, de même leur trône n’est pas leur siège de bureau mais leur bureau lui-même, la pièce, y venir suffit à activer le lien. Les démons ne viennent pas ici pour rencontrer Belial, il n’y a que sous l’effet de l’ignorance la plus totale ou de l’urgence qu’ils ne le font, et généralement ce sont des daemons de Belial elle￾même qui viennent, elle n’est pas contre l’idée d’en recevoir d’autres mais l’irrespect de consulter la reine directement sans en référer à ses supérieurs ou à sa propre divinité constitue possiblement un crime tant envers le dieu, ainsi shunté, qu’envers Belial, à qui l’on fait perdre du temps. Les ducs de Belial en revanche sont régulièrement invités à venir dans son bureau."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Demona Prince ; Belyandra Queen."}]}],"illustration":{"src":"images/points-rencontre/cabinet-faith.webp","alt":"Cabinet Faith","caption":"Cabinet Faith"}},{"id":"points-rencontre-night-feathers","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Night Feathers","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Daemons"],"sections":[{"id":"dossier-daemons-23","title":"Rôle pour Daemons","level":2,"blocks":[{"type":"p","text":"Située à quelques minutes du quartier abandonné de Veronica Silver, la moitié de ce bar enterré est dans le quartier sans loi, l’’autre moitié dans un bout de quartier Gouvernemental, mais sous une ancienne caserne de recrutement. Discret et impossible à trouver par hasard, son entrée est dans une ruelle sombre et étroite, trop étroite pour y mettre une voiture, à peine une benne à ordures. C’est un bar de l’Association. Il fournit de l’armement par des casiers si les chasseurs ont le bon insigne et le bon rang. Tout semble old school, miteux, mais rien ne l’est vraiment. L’ambiance est assez morte généralement, les gens discutent à mi-voix, se regardent avec méfiance, il n’est pas rare qu’ils ne discutent qu’avec ceux qu’ils connaissent déjà, et le personnel du bar, ici, un certain Barret Kelvin (Barrachiel) est le barman, un petit gros assez acide et moqueur, méprisant même, bien qu’il cherche toujours à aider les nouveaux venus ; Le bar est rempli d’» Observateurs » mêlés aux « Chasseurs », les observateurs peuvent être des corneilles, ça arrive assez souvent. Le bar des « Nigh feathers » a malgré tout une communauté de chasseurs plus occulte que le reste, ils chassent rarement des elfes ou des extraterrestres. Le Hunt15 est tenu en grande estime, sur les murs du bars, de faux articles journaux en papier sont imprimés pour servir aux nouveaux, afin qu’ils lisent les grandes chasses les ayant consacrés. Certaines informations plus stupides sont aussi reléguées, le nombre de fois que « le « faucheur noir » a parlé, le nombre de fois où on a vu la « blonde de Cypher », le nombre de fois où Aslisa a finie nue, et d’autres palmarès moins glorieux pour humaniser les chasseurs les plus connus. Ce bar possède comme singularité de voir Morrighan en personne tenir le comptoir parfois, sous le nom de « Mary Gaine », remplaçant Barret Kelvin de temps en temps, elle s’y est déjà faite draguée par sa fille, Ciara, qui ne pouvait la reconnaitre notamment."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Barret KELVIN ; Ameena al-Gad."}]}],"illustration":{"src":"images/points-rencontre/night-feathers.webp","alt":"Night Feathers","caption":"Night Feathers"}},{"id":"points-rencontre-raven-corporation-hq","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Raven Corporation HQ — Black Tower","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Daemons","Rocréens & aliens"],"sections":[{"id":"dossier-daemons-25","title":"Rôle pour Daemons","level":2,"blocks":[{"type":"p","text":"La corporation de la raven industries a pour siège un immense building noir surnommé « Black Tower » ou « Raven tower ». C’est là que l’essentiel des décisions pour la corporation sont prises, que les plus grands ingénieurs travaillent et que les plus grands directeurs logent également. Y logent quelques notables également, proches de Morgan Brandubh. Pendant que dans les bas étages les projets d’armement ou de véhicules du futur sont développés, les décisions plus politiques s’opèrent au-dessus, plus au-dessus encore, Morrghan possède de grandes salles de réunions où se rassemble les mages de sa Loge de New-York quand ils viennent lui rendre visite à Los Angeles. C’est la loge secondaire de New￾York en quelque sorte. La sécurité est essentiellement humaine, mais même si la tour dorée attaquait, la raven pourrait envoyer un « simple » missile sans user du moindre sort et si la Tour dorée est imprenable, certes, les familles des mages, leurs amis, toute personne liée à n’importe quel mage la loge de LA finirait tué sans aucun sort nécessaire, de quoi faire réfléchir les plus puissants, la raven, rien que dans la Réalité pouvant oblitérer n’importe quel réseau ou plan de la Vérité pratiquement. Ajoutons la possibilité que Morgan n’invoque Daghain et on saisit le principe de Guerre froide entre les Loges. Et cela, c’est en oubliant que Morrighan, en vérité est une déesse et la tour son grand Temple. Outre les Mages, donc, qu’elle peut loger, il y a donc ses grands prêtres, ses grands corbeaux et ses ducs daemoniaques travaillant à la Raven. Le QG de la raven est prévu pour recevoir ses corneilles et ses daemons, des ascenseurs spéciaux existent pour qu’ils ne prennent pas les mêmes que ceux des employés classiques, plus un agent de Morrighan est haut classé, plus il rencontre des daemons ou des corbeaux de renommées, avant de voir la déesse elle-même. L’agent peur se renseigner, s’équiper et se faire soigner aux frais de la Raven en y venant, en revanche, s’il ne vient pas, il ne reçoit rien ou presque, peu d’infos, peu de matériel et peu de bénédictions divines."}]},{"id":"dossier-rocreens-aliens-51","title":"Rôle pour Rocréens & aliens","level":2,"blocks":[{"type":"p","text":"La corporation de la raven industries a pour siège un immense building noir surnommé « Black Tower » ou « Raven tower ». C’est là que l’essentiel des décisions pour la corporation sont prises, que les plus grands ingénieurs travaillent et que les plus grands directeurs logent également. Y logent quelques notables également, proches de Morgan Brandubh. Pendant que dans les bas étages les projets d’armement ou de véhicules du futur sont développés, les décisions plus politiques s’opèrent au-dessus, plus au-dessus encore, Morrghan possède de grandes salles de réunions où se rassemble les mages de sa Loge de New-York quand ils viennent lui rendre visite à Los Angeles. C’est la loge secondaire de New￾York en quelque sorte. La sécurité est essentiellement humaine, équipée d’armes humaines, de technologie humaine de 2035 et pourtant, aucun Ad’rak de l’armée noire ou même le moindre escadron de l’AIDH ne saurait monter dans cette tour tant elle est bien défendue. Le directeur de sous-branche, Rached Kelley ( Raysh’kan Feeshri) loge à la Tour, s’il n’est pas aussi importance qu’un directeur de branche, un vice-président ou la présidente, c’est un des plus haut cadre de la raven malgré tout. C’est aussi le clone du plus grand empereur Rocréen ayant existé, doté des plus puissants pouvoirs qu’aucun rocréen n’a jamais développé et c’est pour ça que sa lignée est si influente. Il dirige la faction Feeshri d’une main de fer et a pour projet de détruire les Shadiri, afin de récupérer le marché noir mais ce n’est pas aisé. Il est très obéissant envers la seigneur-général ayant anéanti son empire à l’époque : une certaine Morrighan et travaille pour elle docilement pour cette raison, sans aucune forme de volonté vengeresse, au contraire. En venant à lui, les Extrals jouent un jeu aussi dangereux que légal, en effet, Raysh estlà légalement, avec l’accord de l’AIDH, il travaille légalement pour Morgan brandubh et sa richesse est légale, pas comme les Shaediri, totalement criminels et illégaux."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Barbara Uí Maotháin ; Morgan Brandubh ; Rached KELLEY ; Racheyl Rosemann."}]}],"illustration":{"src":"images/points-rencontre/raven-corporation-hq.webp","alt":"Raven Corporation HQ — Black Tower","caption":"Raven Corporation HQ — Black Tower"}},{"id":"points-rencontre-runyon-canyon","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Tanières de Runyon Canyon","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Loups-garous"],"sections":[{"id":"dossier-loups-garous-27","title":"Rôle pour Loups-garous","level":2,"blocks":[{"type":"p","text":"Le parc fut grandement abandonné pendant la grande crise économique, avec le réchauffement climatique, il était devenu beaucoup plus aride et sec, heureusement, la Tuatha prenant une place incommensurable à Hollywood, la corporation acheta le par cet lui rendit sa couleur plus verte d’antan. Loué au gouvernement et à la municipalité par la Tuatha, le parc est ouvert au public bien que certaines parties soient fermées pour des tournages à l’occasion. Depuis longtemps, le parc assez boisé et naturel a toujours servi à la rencontre des Loups-garous en Californie. S’ils affectionnent le grand air, les forêts, plaines et déserts ont malheureusement l’inconvénient d’être bien trop vastes, les parcs, dans ce style, sont le meilleur compromis entre nature et accessibilité. Les factions de Garous possèdent des tunnels cachés, ils appellent cela « des Tanières » mais on devrait plutôt les comparer à des bunkers. La localité a tendance a primé pour els garous, même si la guerre entre les factions peut être sanglante, ils s’aideront plus volontiers qu’ils ne se déchireront, tant ils sont peu nombreux. Les tanières servent de planquent à ceux recherchés, blessés ou qui perdent le contrôle. Les médecins y résidant sont nourris par ceux ayant besoin de leurs services, on les surnomme « nudistes » ou « galeux », pour signifier qu’ils n’ont pas de « Pelage », pas de faction, même si ça parait péjoratif, à la base n’étant que des parias se rassemblant faute de faction, il est rare qu’on s’en prenne à un « galeux » en 2035, ils ont gagné un certain prestige et font désormais le liant entre les meutes de différentes factions. Les garous se rendent à la tanière pour voir d’autres garous, les informations sur l’Holonet se diffusent bien mais le contact physique est inestimable pour eux. Outre les soins, faux papiers et faux Logifates, les tanières servent de cachent d’armes dont des fléchettes anti-Wendigo ou des seringues anti-faramine pour éviter la contamination."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Jeff Bezos ; Rishabha Ajagavakar."}]}],"illustration":{"src":"images/points-rencontre/runyon-canyon.webp","alt":"Tanières de Runyon Canyon","caption":"Tanières de Runyon Canyon"}},{"id":"points-rencontre-ivory-fangs","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Ivory Fangs","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Loups-garous"],"sections":[{"id":"dossier-loups-garous-29","title":"Rôle pour Loups-garous","level":2,"blocks":[{"type":"p","text":"La base « Ivory fangs » est une base militaire de l’Independant Californian Army. (ICA). Tenue par le colonel Benedicte VILHELMSEN (Thorunn), la base contient uniquement des Forces Spéciales, notamment l’ équivalent californien des Bérets Verts. Dans un premier temps, on pourrait considérer comme difficile d’approcher la Grande meneuse des Pelages blancs en venant dans une base militaire principalement remplie de troupes d’élite. En vérité, la base possède un pôle de recrutement et un autre de surveillance qui sont assez actifs, c’est précisément ce pôle de recrutement qui est la porte d’entrée aux garous. Tous les Pelages blancs ont une tête de Fenrir sur le dos, énorme sur tout le doou très discret au-dessus des fesses, sur la nuque, peu importe, ils l’ont tous, ainsi, à la visite médicale obligatoire, le personnel soignant n’a rien besoin de demander, orientant les visiteurs vers un Alpha ou un meneur. Thorunn se sert de ss garous comme de soldats, de gradés, presque tous ont une formation au combat, Thorunn est en guerre, outre les Pelages gris qu’elle déteste, elle lutte contre les Faramines et la contamination de Vhodhal. Etant donné le caractère indépendant de la base, ayant des affinités secrètes avec l’armée d’Andrea SHIELD, Thorunn se permet le prêt d’armement de guerre à certains de ses hommes non militaires et peut allouer des soldats non-garous à des missions ayant un intérêt uniquement pour les velus. Elle reste toutefois discrète et efficace. Elle passe notamment à travers la grande réserve par ses convoyeurs privés, Eversor pour acheminer du matériel. Les crawlers et chasseurs les plus atypiques sont toutefois invités à ne pas se rendre à la base s’ils ne veulent pas finir rasés et à faire des pompes quelques jours parmi les soldats."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Clyde W. McShark - Ulfried ; Benedicte VILHELMSEN."}]}],"illustration":{"src":"images/points-rencontre/ivory-fangs.webp","alt":"Ivory Fangs","caption":"Ivory Fangs"}},{"id":"points-rencontre-wild-angel-wolf","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Wild Angel Wolf","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Loups-garous"],"sections":[{"id":"dossier-loups-garous-31","title":"Rôle pour Loups-garous","level":2,"blocks":[{"type":"p","text":"Le bar est situé à Angeltown, un village de bikers, tenu par les Hell angels, c’est le QG d’Arthur Bartram, le grand boss de ces motards terrifiants. Ce n’est pas à Los Angeles-même, cependant, c’est assez proche et assez isolé. Le bar a été construit en partie par Frederic Jackelston » dit « Jackal », Maddox Sharp dit « Moose », Arthur Bartram dit « Bear » et Ephraim Bahal dit « Bull », des vétérans de la guerre de 22-28, seuls les deux premiers restant des hells Angels. Bien que « Jackal » ne soit plus à Angeltown, nombreux sont les garous y étant resté au sein ds pelages blancs. Les « ulfhednars » notamment, cette élite garou, un peu neonazi sur les bords qui, de manière assez hérétique selon les traditions garou, pratiquent la « dévoration » alors qu’ils ne sont pas des Grands Meneurs. C’est ainsi que Thorunn, qui en était une, a remplacé le précédant grand meneur durant le moyen Age. On trouve plus aisément des contacts de pelages blancs et le coté militaire n’est pas là, en revanche, il faut avoir les couilles de venir à Angeltown, des centaines de dangers sur la route pouvant survenir. Le bar n’est pas uniquement tenu par les garous, en vérité, Bartram est un Berserk d’Aèr, le bar est donc plutôt orienté berserk d’Aèr, lycans d’Aèr, mais malgré tout, les deux communautés (Aèr et Terre) ne se confrontent pas, dans la Réalité, ils sont amis et ignore quelle vérité est cachée, hormis Bartram qui sait ce qu’est Thorunn et inversement, même s’ils le taisent. Thorunn est d’ailleurs régulière ici, elle préfère s’y détendre plus qu’aller à Los Angeles-même. Les garous viennent pour échanger du matos plus qu’autre chose, des prisonniers aussi. Les « ulfhednars » n’hésitent pas à bouffer les Alphas et Meneurs d’autres factions quand ils les capturent et qu’ils ont fait du mal à leurs meutes."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Murton Keens ; Frederic Jackelston « Jackal »."}]}],"illustration":{"src":"images/points-rencontre/wild-angel-wolf.webp","alt":"Wild Angel Wolf","caption":"Wild Angel Wolf"}},{"id":"points-rencontre-jadecenter-palameta","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Jadecenter « Palameta »","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Orques & gobelins"],"sections":[{"id":"dossier-orques-gobelins-35","title":"Rôle pour Orques & gobelins","level":2,"blocks":[{"type":"p","text":"Le syndicat de Jade utilise peu les Silcenters, ces bar-hôpitaux pour expatriés d’Aèr, ces derniers sont surtout destinés aux citoyens que le conseil protège, les orques et les gobelins « nuisibles », ne l’étant pas. Les « Jadecenters » sont l’équivalent des Silcenters, même s’ils sont plus undergrounds et plus secrets. On y entre comme pour le coté fantastique d’un bar de chasseur, en prenant l’entrée révélée. Les Jadecenters sont surtout tenus par des gobelins en général, ils ont un meilleur sens des affaires et laissent la sécurité à des orcs, qui ont un meilleur sens du combat. C’est l’exact opposé à Palameta. Tenu par Alsha, une fille du légendaire Ashorn, le lieu est défendu par plus de deux cents gobelins, au lieu d’avoir quelques gorilles aux issues, elle les a placés dans les aérations, des placards et toute sortes de cachettes confortablement aménagées d’où ils peuvent sniper en toute impunité ceux qui dérangeaient et sans qu’aucun client de voit aucune arme ni aucune sécurité, juste un café underground convivial tenu par une belle et plantureuse créature. Palameta peut être le café pour retrouver des gobelins ou des orcs, des amis, de la famille, mais c’est aussi un haut lieu, si ce n’est LE plus gros centre de rencontre du Syndicat de jade, cette mafia orco-gobeline de la Vérité. On s’y revend du matériel du marché noir magique, on s’y présente les « bonnes personnes », on peut y croiser Atreesha ou Martin Green, parmi les gobelins les plus influents, Ashorn, Grim ou bien Shiloh Floyd pour les orcs. Généralement, les crawlers orcs travaillent qu’ils le savent ou non directement pour Alsha cependant. Elle veut se faire appeler « mère » par ses larbins et attends qu’ils ne jouent un rôle de fils obéissants. Elle peut « donner le sein » aux plus méritant ou bien « fesser » les mauvais, des termes qui sont bien plus sérieux qu’on ne le penserait."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Alsha Ashorn ; Jackson Blade."}]}],"illustration":{"src":"images/points-rencontre/jadecenter-palameta.webp","alt":"Jadecenter « Palameta »","caption":"Jadecenter « Palameta »"}},{"id":"points-rencontre-green-health","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Green Health — Fall Avenue","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Orques & gobelins"],"sections":[{"id":"dossier-orques-gobelins-37","title":"Rôle pour Orques & gobelins","level":2,"blocks":[{"type":"p","text":"La salle de sport « green Health » est en vérité une chaine de salles de sport, tous les bâtiments sont des immeubles complets, de 5 étages, chaque étage possède quatre salles à l’exception du rez-de-chaussée qui est une piscine olympique et une partie sauna. Le toit du bâtiment est aménagé pour être un terrain de football, au centre d’une piste de course. Située sur Fall Avenue, le bâtiment en question est en face de la caserne de Recrutement des Independant Californian Marines (ICM), le grand héros Général Ashorn possède cette salle et toute la chaine des Green Health ». Les moniteurs sont d’anciens militaires plus ou moins invalides ou traumatisés. Ashorn ayant été le supérieur direct d’une certaine Siobhain Nic Siridean et le premier officier à vraiment l’avoir exposée au danger en toute confiance, elle lui a rendu cela, Green Health étant une marque de la branche « Santé et bienêtre » de la Tuatha, le finançant donc, ayant ainsi les meilleurs formateurs pour les cascadeurs et acteurs en retour. Bien que ce lieu ne soit pas initialement prévu pour être un lieu de rencontre pour les orcs, ils ont très vite commencé à devenir la majorité des clients réguliers. Certains étages et donc certaines salles sont entièrement privatisées pour les orcs désormais. De même, du côté de la piscine, certaines salles ne sont pas des saunas mais des salles de régénérations utilisant des boues traditionnelles orcs, plus adaptées à leurs peaux épaisses et leurs muscles denses. Green Health permet aux orcs une remise en forme et un entretien de leur corps, on y vend également des compléments alimentaires plus adapté à l’organisme orc, afin qu’ils n’aient le poil plus soyeux et les yeux plus vifs. La culture orque, sur Terre, est assez individualiste, il faut comprendre que les communautés ont toujours été peu nombreuses, isolées, ils ont plus souvent été amenés à vivre parmi d’autres communautés qu’entre eux, bien avant l’Hologramme, ceci a pour conséquences qu’ils n’ont pas un si grand besoin de se réunir et qu’une fois entre eux, ils sont très compétitifs."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Gerald Ashorn ; Judy Rosheen Smith."}]}],"illustration":{"src":"images/points-rencontre/green-health.webp","alt":"Green Health — Fall Avenue","caption":"Green Health — Fall Avenue"}},{"id":"points-rencontre-fuckalifornia","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Fuckalifornia","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Orques & gobelins"],"sections":[{"id":"dossier-orques-gobelins-39","title":"Rôle pour Orques & gobelins","level":2,"blocks":[{"type":"p","text":"Le bar est caché dans le quartier abandonné sans nom près de la plage, il est souterrain, donc en cas d’échange de feu ou pire, il est souvent un lieu où la population du quartier peu se réfugier. Bar de neopunks désormais, il a été fondé par des insurgés en vérité, l’esprit anarchiste y étant une quasi-religion. Les insurgés s’y rendent toujours, notamment Kristian Morales (Kran’Rag) qui a grandement payé pour l’entretenir. Même si le bar a l’air d’un dépotoir, qu’il est aussi laid et taggué qu’une ruelle, aussi mal rangé que la chambre d’un hikikomori, c’est un lieu vraiment adoré, et très souvent visité, même s’il n’a pas de grande salle large, il est un dédale d’angles droits serpentant sous le quartier abandonné. La petite scène du bar est le lieu de représentation et d’expérimentation de The Void, le groupe où Kristian est batteur, c’est là qu’on a vu Darlene le plus souvent. Le Fuckalifornia est un bar anarchiste, neopunk et insurgé très militant, il vaut mieux s’y rendre en ayant des idées très précises de ce qu’il faut dire et comment le dire, sinon on y perd souvent une ou deux dents. C’est aussi un repaire à orcs, Kristan Morales étant le chef d’un petit gang exclusivement orc, les « Greenvoids », des références chez les crawlers, notamment les assassins. Ils ne passent pas aucun fixer, aucunement la Blanchisserie et aucun intermédiaire, ils répugnent les mafias – hormis le syndicat de jade- les corporations encore plus et ne considèrent pas le gouvernement. Leur seul but est d’éliminer des chiens du système corrompu, alors ils offriront toute l’aide, le soutient et l’équipement désiré à ceux qui ont ce genre d’idéaux ou, à défaut, de cibles, quelque soient les raisons derrière."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Kristian Morales ; « Annallica » Anna Hetfield."}]}],"illustration":{"src":"images/points-rencontre/fuckalifornia.webp","alt":"Fuckalifornia","caption":"Fuckalifornia"}},{"id":"points-rencontre-dream-vladic-tower","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Dream Vladic Tower","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Orques & gobelins"],"sections":[{"id":"dossier-orques-gobelins-41","title":"Rôle pour Orques & gobelins","level":2,"blocks":[{"type":"p","text":"La « Tour des rêves Vladic » est un monument de l’architecture d’après-guerre, plus grand building avant les tours corporatistes ou Neovatican, c’était une démonstration de force des travailleurs russes expatriés. Hélas ou plutôt heureusement, les normes corporatives puis gouvernementales ont invalidé la possibilité d’y loger des gens comme prévu à la base, construite en deux semaines, du jamais vu, elle fut désignée comme instable structurellement et fermée, la Vladic association ayant à sa charge de détruire le bâtiment, elle ne le fit jamais. De base, Drasko Vladic savait la tour impossible à faire habiter et ne l’avait pas prévue ainsi. Elle est dans un quartier abandonné, à moitié possédée par la mafia russe. La tour sert de prison, salles de tortures, chambre de reconditionnement de prostituées et autres joyeusetés que la mafia peut faire, c’est aussi une cache d’armes. La personne qui en a la charge n’est autre que « Grim » Grigoria RAVINSKY, une ukrainienne, du groupe personnel de Drasko, elle compte, avec la jeune tarée, Zoya RYUKANA comme une des plus proches de Drasko, bien qu’elle ne soit sortie de prison que récemment. Elle est la maitresse de la « tour des rêves ». Bien qu’elle soit à moitié Fléau, Grim est une personne relativement ouverte à aider les orcs et lutter contre els aberrations et les fléaux mineurs. Elle garde son katana scellé, « Turuhoken » toujours caché, le fléau mineur dedans étant un frère à elle. Dans la tour des rêves, elle offre son sang aux orcs acceptant les souffrances allant avec, afin de confier une force accrue. En échange, elle leur confie des tâches pour devenir des combattants opposés aux Fléaux. Pour ceux qui ne sont pas prêts, elle est vaguement à peine plus concernée que s’ils étaient des gobelins."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : « Grim », Grigoria RAVINSKY ; Valentyn Solovej."}]}],"illustration":{"src":"images/points-rencontre/dream-vladic-tower.webp","alt":"Dream Vladic Tower","caption":"Dream Vladic Tower"}},{"id":"points-rencontre-military-next-academy","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Military Next Academy","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Orques & gobelins"],"sections":[{"id":"dossier-orques-gobelins-43","title":"Rôle pour Orques & gobelins","level":2,"blocks":[{"type":"p","text":"La MNA (military next academy) est une académie militaire gouvernementale qui fournit aux corporations ou aux armées des élèves officiers de formation rigoureuse. La directrice est Kimberley VASQUEZ (Kiarn Kay), une ancienne subordonnée et soutien proche de Rick SCOTT, le numéro 2 d’Ushkoll security. Elle est financée par les corporations mais dès qu’une d’entre elle ouvre ses propres académies militaires, elle a tendance à voir ses diplômés mécontents et se tourner, - forcément – sur l’anti-corporatisme, l’insurrection et causer des ravages, ce qui laisse les corporations revenir sur l’idée de diminuer de trop le budget qu’elles allouent. La raison qui rend les officiers sortant de cette académie si efficace ? Les formateurs sont tous des orques de la horde divine, la horde divine est le clan d’Ashorn, sa « tribu », qu’il amena avec lui d’Aèr, et dont on dit qu’elle serait elle-même issue des orcs qu’une divinité orque aurait laissé de sa propre horde en quittant Aèr autrefois. En bref, ils descendent de héros eux-mêmes descendants de héros légendaires et n’ont pour objectif que d’être digne d’Ashorn, leur maitre. Tous les orcs peuvent se présenter à Kiarn, la directrice, elle les fera former, équiper, mais leur dévotion sera alors totale envers Ashorn. Elle dispose de forts liens avec Ushkoll security, Tortoise security, Pixy security mais aussi les armées Californienne et des Etat-Unis. « La horde divine » -que l’académie dissimule-est une faction de chasseurs de haute élite, elle rivaliserait sans mal avec la Chasse Fantastique de Titania, mais les guerriers ont bien plus d’honneurs, ils ne s’attaquent pas à du menu fretin, l’intégrer est un prestige sans égal pour un orc."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Kimberley VASQUEZ ; Jordan Mulkenny."}]}],"illustration":{"src":"images/points-rencontre/military-next-academy.webp","alt":"Military Next Academy","caption":"Military Next Academy"}},{"id":"points-rencontre-space-union-aidh","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"QG Space Union Force / bureau californien de l’AIDH","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Rocréens & aliens"],"sections":[{"id":"dossier-rocreens-aliens-45","title":"Rôle pour Rocréens & aliens","level":2,"blocks":[{"type":"p","text":"L’AIDH est LA plus grande force d’autorité dans la galaxie, il s’agit d’une vaste structure militariste et intrinsèquement spéciste dédiée à la défense de l’Humanité exclusivement dans toute la galaxie. L’AIDH possède un vaste domaine d’influence dans la galaxie et se décompose en de très nombreuses armées, d’immenses effectifs gardiens de secteurs. Dans les secteurs sous protection de l’AIDH, sont toutefois totalement toléré des espèces Aliens, parfois, de maigres communautés humaines suffisent à obtenir la protection de l’AIDH. Les espèces entièrement alliées à l’AIDH disposent aussi d’un statut de protection, essentiellement celles situées en bordures des secteurs défendus (Mo’sen ou Thalsios par exemple). Le statut singulier de la Terre nécessite un Seigneur-Général Singulier, l’héroïne Lisa Erédhès est cette personne. Elle commande à son armée et cette dernière gère l’accès aux Extrals dans le système solaire de la Terre puis l’accès ou non à la Terre elle-même. Le GAAC, qui constitue la force politique derrière l’union des races Extrals possède son bureau au sein-même de la base californienne de l’AIDH. Le flux d’entrée et de sortie de l’atmosphère est réglementé même si les plus gros spatioports restent en antarctique, et en Australie, dans des déserts humains pour limiter au mieux les efforts de l’Hologramme. Bien que ce soit structure militariste, la « Space Union » est une corporation écran pour l’AIDH, elle est donc théoriquement civile et gère l’accès à la base lunaire, ainsi, les Extrals peuvent se faire passer pour des touristes Terre-Lune. La lune étant un territoire corporatif, de fait, de la Space union, gère les visas d’accès à la Lune et de retour, une façon aisée de gérer ceux d’entrée-sortie de la Terre."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Lisa Eredhes ; Kirstyn Kjoll."}]}],"illustration":{"src":"images/points-rencontre/space-union-aidh.webp","alt":"QG Space Union Force / bureau californien de l’AIDH","caption":"QG Space Union Force / bureau californien de l’AIDH"}},{"id":"points-rencontre-shaediri","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Quartiers du clan Shaediri","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Rocréens & aliens"],"sections":[{"id":"dossier-rocreens-aliens-47","title":"Rôle pour Rocréens & aliens","level":2,"blocks":[{"type":"p","text":"« Extrals » (extraterrestrial beings) est le surnom des aliens, les expatriés galactiques sur Terre. Il existe, en gros, trois types d’Extrals : les officiels, les natifs et les illégaux. Les deux premières catégories sont soumises à la surveillance de l’AIDH et du GAAC qui assurent que ces ressortissants ne causent pas de soucis auprès de la population terrienne. On n’attend pas que la Terre convienne aux Extrals, ils viennent visiter ou s’adapter, et parfois cela réduit leur espérance de vie, par exemple c’est le cas des Thalsios ou des rocréens, même des Talass. La dernière catégorie, les illégaux n’a donc aucune protection, aucune possibilité d’intégration, c’est en cela que l’alliance du clan Shaediri s’est imposé à Los Demonos, sous Los Angeles et a grandement contribué à créer « le marché noir » tel qu’il est aujourd’hui, pas seulement un marché illégal de technologies importée mais de services, de conseil, afin d’améliorer la survie de chacun des Extrals sans mettre en danger leurs vies. La mafia Rocréenne (clan shaediri) est issues de peuples rocréens asservies et malmenés, ces esclaves ont été libéré par la destruction de l’empire Rocréen autrefois, ls Shaediri se sont réfugié sur Terre comme un sanctuaire loin de leurs tortionnaires et ont un fort sens de la défense des opprimés : Ils ont protégé des greys, des orpacyors, losus ou des ad’rak , presque toujours issus de communautés oppressées ou massacrées, créant ainsi sur Terre, des groupes de différentes espèces, parfois très Hostiles dans la galaxie, mais s’entendant toutes ici. Les Rocréens de ce clan imposent le système de « points de crédits », ils n’acceptent pas la monnaie galactique (dykals) alors ils offrent aux Extrals venus d’ailleurs une quantité de PdC qui peut, comme son nom l’indique être augmentée à loisir, se payant plus tard sous forme de services ou de demandes. C’est la faction extrals la plus influente."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Ivana YEVGENIEVNA ; Ernesto Hidalgo."}]}],"illustration":{"src":"images/points-rencontre/shaediri.webp","alt":"Quartiers du clan Shaediri","caption":"Quartiers du clan Shaediri"}},{"id":"points-rencontre-feeshri","dataset":"points-rencontre","category":"Vérité","sourceCategory":"Vérité","title":"Quartiers du clan Feeshri","source":"Points de rencontre(3).pdf","status":"canon_source","rebuildV2":true,"audience":"mj","tags":["Vérité","Points de rencontre","Rocréens & aliens"],"sections":[{"id":"dossier-rocreens-aliens-49","title":"Rôle pour Rocréens & aliens","level":2,"blocks":[{"type":"p","text":"« L’empire azuré » ou « clan Feeshri est une faction vestigiale, dans la galaxie, elle a une place écrasante sur de nombreux mondes encore puisqu’il s’agir des restes de l’empire rocréen. Cette partie du marché est fermée aux Shaediri mais pas aux autres Extrals. Les technologies sont toutefois bien plus adaptées aux Rocréens de ce clan et leurs pouvoirs spécifiques. Cette partie du marché est aussi surtout sur le commerce ADN très lié à ce clan. Technologiquement, les Feeshri offrent de l’armement d’un niveau TRES au-dessus de ce qu’offre les Shaediri, en effet, les Feeshrii sont un relais des G-corporations, les corporations galactiques que l’AIDH, les Shaediri et le GAAC empêchent scrupuleusement de percer et même d’approcher des corporations terriennes, si ridiculement locales. Ils ont aussi, plus occasionnellement, alliés aux Roesis que le GAAC empêche également totalement de s’installer sur Terre. Bien que membres du marché noir, TOUS les Feeshri sont des cadres, des riches et des gens influents dans la Réalité, ceux qui ne le sont pas sont des erreurs, des parias, des sous-merdes qui se feront mépriser comme rarement par leurs pairs. C’est pour ça qu’aucun Feeshri n’est crawler ou chasseur, ils viennent tous de l’extérieur de la Terre, alors que les Shaediri eux, sont à 95% natifs de la Terre et peuvent pourvoir ce genre de métier sans mal ni décalage quand un Feeshri serait un touriste perdu et dangereux pour lui-même. La santé des Feeshri est plus difficile à maintenir sans équipements adapté, mais ils possèdent des dons psychiques dignes de l’ordre Scytheri, ces maitres de la force mentale. Toutes les armes Feeshri sont des armes « mentales », qui se basent sur leurs pouvoirs et les amplifie plutôt que des armes à projectiles ou à énergie."}]},{"id":"gardiens","title":"Gardiens","level":2,"blocks":[{"type":"p","style":"lore","text":"Gardiens : Leia IRVING ; James Hopper."}]}],"illustration":{"src":"images/points-rencontre/feeshri.webp","alt":"Quartiers du clan Feeshri","caption":"Quartiers du clan Feeshri"}}] as Array<Record<string, any>>;
